   SET MIL_STAT_CD = #{milStatCd}, END_ODO_KM = #{endOdoKm}, END_REG_DT = #{endRegDt}, END_EMP_ID = #{endEmpId},
       END_TX_ID = #{endTxId}, DRIVEN_KM = #{drivenKm}, ANNUAL_KM = #{annualKm}, REFUND_RATE = #{refundRate},
       REFUND_BASE_PREM = #{refundBasePrem}, REFUND_AMT = #{refundAmt}
 WHERE CONTRACT_NO = #{contractNo}
